using System;using System.IO;using System.Text;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using SargasPC;
class CoreTests {
 static int n;static void Check(bool b){n++;if(!b)throw new Exception("PC host case "+n);}static void Reject(Action a){bool failed=false;try{a();}catch{failed=true;}Check(failed);}
 public static void Main(string[] args){string root=Path.Combine(args[0],"host-qa-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
  string h=Data.Digest(Encoding.ASCII.GetBytes("abc"));Check(h=="ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad");Check(Data.Hash(h));Check(!Data.Hash(h.ToUpperInvariant()));Check(!Data.Hash("bad"));
  Check(Data.ParseHashes(new StringReader("# source\n"+h.ToUpperInvariant()+"\n"+h)).Count==1);Reject(()=>Data.ParseHashes(new StringReader("bad")));Reject(()=>Data.ParseHashes(new StringReader(new string('a',257))));Reject(()=>Data.ParseHashes(new StringReader(new string('\n',100001))));
  Check(Data.Bounded(new MemoryStream(new byte[10]),10,null).Length==10);Reject(()=>Data.Bounded(new MemoryStream(new byte[11]),10,null));Reject(()=>Data.Bounded(new MemoryStream(new byte[1]),10,()=>{throw new OperationCanceledException();}));
  Check(Data.Endpoint("https://example.com/base").ToString()=="https://example.com/base/");foreach(string raw in new[]{"http://example.com","https://user:pw@example.com","https://example.com/?key=secret","https://example.com/#fragment","not a URL"})Reject(()=>Data.Endpoint(raw));Check(Data.Token("test-api-key")!="");foreach(string token in new[]{"","abc\nsecret","white space",new string('x',513)})Reject(()=>Data.Token(token));
  var decoded=Data.Json().Deserialize<Dictionary<string,object>>("{\"query_status\":\"ok\",\"data\":[{\"sha256_hash\":\""+h+"\"}]}");Check(decoded["data"] is IList);Check(((IList)decoded["data"]).Count==1);
  string file=Path.Combine(root,"sample.txt");Data.Atomic(file,"abc");Check(File.ReadAllText(file)=="abc");Data.Atomic(file,"xyz");Check(File.ReadAllText(file)=="xyz");Check(Directory.GetFiles(root,"*.tmp").Length==0);
  var core=new Core(Path.Combine(root,"data"));Check(core.Database().Count==0);string engineBin=Path.Combine(core.EngineRoot,"clamav-1.4.6.win.x64");Directory.CreateDirectory(engineBin);Directory.CreateDirectory(core.EngineDatabase);File.WriteAllText(Path.Combine(engineBin,"clamscan.exe"),"");File.WriteAllText(Path.Combine(engineBin,"freshclam.exe"),"");File.WriteAllText(Path.Combine(core.EngineDatabase,"main.cvd"),"");File.WriteAllText(Path.Combine(core.EngineDatabase,"daily.cld"),"");string evidence=core.LocalEngineEvidence();Check(evidence.Contains("VARIKLIO IR BAZIŲ BŪSENA PATIKROS METU")&&evidence.Contains("Pagrindinės bazės yra")&&evidence.Contains("daily failo pakeitimas")&&evidence.Contains("Failo data nėra parašo ar bazės galiojimo patvirtinimas"));var limit=LocalEngine.Parse(new CommandOutput{ExitCode=1,Output="C:\\Chrome\\chrome.dll: Heuristics.Limits.Exceeded.MaxFileSize FOUND\nInfected files: 1\nScanned files: 25\n",Error=""});string formatted=LocalEngine.ReportOutput("C:\\Chrome\\chrome.dll: Heuristics.Limits.Exceeded.MaxFileSize FOUND\nInfected files: 1\nScanned files: 25\n",limit);Check(!limit.Found&&limit.Incomplete&&formatted.Contains("failas nepatikrintas; tai nėra viruso radinys")&&formatted.Contains("SARGON viruso žymų radinių: 0")&&!formatted.Contains("Heuristics.Limits.Exceeded.MaxFileSize FOUND"));var actual=LocalEngine.Parse(new CommandOutput{ExitCode=1,Output="x: Win.Test FOUND\nInfected files: 1\nScanned files: 1\n",Error=""});string actualText=LocalEngine.ReportOutput("x: Win.Test FOUND\nInfected files: 1\nScanned files: 1\n",actual);Check(actual.Found&&actualText.Contains("Win.Test FOUND")&&actualText.Contains("Infected files: 1"));File.WriteAllText(file,"abc");var w=core.Scan(file);Check(w.Hash==h&&w.Size==3&&!w.Test);core.Verify(w);Check(true);
  long stamp=File.GetLastWriteTimeUtc(file).Ticks;File.WriteAllText(file,"xyz");File.SetLastWriteTimeUtc(file,new DateTime(stamp,DateTimeKind.Utc));Reject(()=>core.Verify(w));
  core.Cancelled=true;Reject(()=>core.Scan(file));core.Reset();core.Paused=true;var task=Task.Run(()=>{try{core.Check();return false;}catch(OperationCanceledException){return true;}});Thread.Sleep(100);Check(!task.IsCompleted);core.Cancelled=true;Check(task.Wait(2000)&&task.Result);core.Reset();
  string big=Path.Combine(root,"too-big.bin");using(var f=File.Create(big)){f.SetLength(Core.MaxFile+1);}Reject(()=>core.Scan(big));File.Delete(big);
  string list=Path.Combine(root,"import.hdb");File.WriteAllText(list,h+"\n");Check(core.Import(list)==1);Check(core.Database().Contains(h));File.WriteAllText(list,"bad");Reject(()=>core.Import(list));Check(core.Database().Contains(h));
  string feed=Path.Combine(core.Root,"community.json");long now=DateTime.UtcNow.Ticks;string other=Data.Digest(new byte[]{1});Data.Atomic(feed,Data.Json().Serialize(new Dictionary<string,long>{{other,now-TimeSpan.FromDays(31).Ticks}}));Check(!core.Database().Contains(other));Data.Atomic(feed,Data.Json().Serialize(new Dictionary<string,long>{{other,now+TimeSpan.FromDays(1).Ticks}}));Check(!core.Database().Contains(other));Data.Atomic(feed,Data.Json().Serialize(new Dictionary<string,long>{{other,now}}));Check(core.Database().Contains(other));Data.Atomic(feed,"{\"bad\":1}");Reject(()=>core.Database());Data.Atomic(feed,"{}");
  string eicar="X5O!P%@AP[4\\PZX54(P^)7CC)7}$EICAR-"+"STANDARD-ANTIVIRUS-TEST-FILE!$H+H*";File.WriteAllText(file,eicar,Encoding.ASCII);var test=core.Scan(file);Check(test.Test);File.WriteAllText(file,"neutral");Check(!core.Scan(file).Test);Check(test.Test); // The test flag belongs to the scanned bytes, not to a later path read.
  core.Config.Endpoint="https://example.com";core.SaveSettings();Check(new Core(core.Root).Config.Endpoint=="https://example.com");string settings=Path.Combine(core.Root,"settings.json");Data.Atomic(settings,"invalid");Reject(()=>new Core(core.Root));Check(File.ReadAllText(settings)=="invalid");
  for(int i=0;i<25;i++)core.History("report "+i);Check(Data.Read<System.Collections.Generic.List<string>>(Path.Combine(core.Root,"history.json"),1500000).Count==20);Check(core.PastReports().Contains("report 24"));
  Reject(()=>core.DeleteCopy(new VaultEntry {Id="../outside"}));Reject(()=>core.Restore(new VaultEntry {Id="../outside"},file));Check(Data.Clean("name\n\0"+new string('x',200)).Length<=160);
  Console.WriteLine("PC CoreTests: "+n+" checks passed; host logic only, not Windows DPAPI, Defender, native isolation, UI or installation.");
 }finally{Directory.Delete(root,true);}}
}
